/* ==========================================================================
   Mi RCR — logos.js
   Logo institucional de cada área para el ENCABEZADO del informe, recortado
   de las hojas oficiales (composición aprobada). PNG embebido en data URI.
   "ar" = ancho/alto, para escalar sin deformar.
   ========================================================================== */

window.LOGOS = {
  /* ReCircula */
  recircula: { nombre: "ReCircula", ar: 3.2467, src: "data:image/png;base64," },
  /* Juntos Por La Vida */
  juntos: { nombre: "Juntos Por La Vida", ar: 2.4733, src: "data:image/png;base64," },
  /* Vidrio Mejor Planeta */
  vidrio: { nombre: "Vidrio Mejor Planeta", ar: 2.0467, src: "data:image/png;base64," },
  /* Redes Con Rostro */
  rcr: { nombre: "Redes Con Rostro", ar: 1.2267, src: "data:image/png;base64," }
};

window.logoImg = function (key, alto) {
  var Q = window.LOGOS[key];
  if (!Q) return '';
  var w = Math.round(alto * Q.ar);
  return '<img src="' + Q.src + '" alt="" style="height:' + alto + 'px;width:' + w + 'px;object-fit:contain;display:block">';
};
